// PDFs for the corporate module: member certificates of insurance and employer invoices.
// Both are clearly marked SANDBOX — synthetic: they are generated by a test system for a fictional
// product of a synthetic insurer and have no legal effect.
import PDFDocument from 'pdfkit';
import { db } from '../db.js';
import { now } from '../clock.js';
import { rupees } from '../utils/money.js';

function sandboxBanner(doc) {
  doc.save().rect(50, 40, 495, 26).fill('#fff4e5').restore();
  doc.fillColor('#8a5300').fontSize(10).text('SANDBOX — synthetic. Test document for a fictional product; not a real insurance contract.', 58, 48, { width: 480 });
  doc.moveDown(1.2);
}

function header(doc, title, subtitle) {
  sandboxBanner(doc);
  doc.x = 50;
  doc.fillColor('#087f8c').fontSize(18).text('Vision Health Care');
  doc.fillColor('#555').fontSize(9).text('Technology platform and intermediary. VHC is not the insurer.');
  doc.moveDown(0.6).fillColor('#14283f').fontSize(14).text(title);
  if (subtitle) doc.fillColor('#555').fontSize(10).text(subtitle);
  doc.moveDown(0.6);
}

const row = (doc, k, v) => doc.fillColor('#3a4d63').fontSize(10).text(`${k}: `, { continued: true }).fillColor('#000').text(String(v ?? '—'));

function send(res, filename, build) {
  const doc = new PDFDocument({ size: 'A4', margin: 50, info: { Title: filename, Author: 'Vision Health Care (sandbox)' } });
  res.setHeader('Content-Type', 'application/pdf');
  res.setHeader('Content-Disposition', `attachment; filename="${filename}.pdf"`);
  doc.pipe(res);
  build(doc);
  doc.moveDown(2).fontSize(8).fillColor('#777').text(`Generated ${now().toISOString()} by a demonstration system. All organisations, products, rates and people are synthetic.`);
  doc.end();
}

export function streamCertificate(enrolment, res) {
  const p = db.get('groupPolicies', enrolment.groupPolicyId);
  const m = db.get('groupMembers', enrolment.memberId);
  const emp = db.get('employers', enrolment.employerId);
  send(res, enrolment.certificateNumber, (doc) => {
    header(doc, 'Certificate of Insurance — Group Health', `${p.productName} · issued by ${p.insurerName}`);
    row(doc, 'Certificate number', enrolment.certificateNumber);
    row(doc, 'Group policy', `${p.policyNumber} (insurer reference ${p.insurerReference || '—'})`);
    row(doc, 'Policyholder (employer)', emp?.name);
    row(doc, 'Insurer', p.insurerName);
    row(doc, 'Employee', `${m.name} (employee ID ${m.employeeId})`);
    row(doc, 'Member reference', enrolment.insurerMemberRef);
    row(doc, 'Cover period for this member', `${enrolment.coverFrom} to ${enrolment.coverTo || p.endDate}`);
    row(doc, 'Sum insured (family floater per employee)', rupees(p.terms.sumInsured));
    row(doc, 'Family definition', p.terms.familyLabel);
    doc.moveDown().fillColor('#087f8c').fontSize(12).text('Covered lives');
    for (const l of enrolment.lives) {
      doc.fillColor('#000').fontSize(10).text(`• ${l.name} — ${l.relationship}, DOB ${l.dob}, cover ${l.coverFrom} to ${l.coverTo || p.endDate}${l.status !== 'Covered' ? ` (${l.status})` : ''}`);
    }
    doc.moveDown().fillColor('#087f8c').fontSize(12).text('Group terms (synthetic)');
    for (const w of p.terms.waivers || []) doc.fillColor('#000').fontSize(10).text(`• ${w.label}`);
    doc.moveDown().fillColor('#087f8c').fontSize(12).text('Claims & help');
    doc.fillColor('#000').fontSize(10).text(`Claims: ${p.contacts?.claims?.name} — ${p.contacts?.claims?.phone}, ${p.contacts?.claims?.email}`);
    doc.text(`Insurer group desk: ${p.contacts?.insurer?.name} — ${p.contacts?.insurer?.phone}`);
    doc.text('Find network hospitals in the VHC app under Hospitals.');
    doc.moveDown().fontSize(9).fillColor('#555').text('Cover is subject to the group policy terms agreed between the employer and the insurer. This certificate is evidence of membership only.');
  });
}

export function streamInvoice(inv, res) {
  send(res, inv.invoiceNumber, (doc) => {
    header(doc, inv.direction === 'credit' ? 'Credit note' : 'Tax invoice', inv.typeLabel);
    row(doc, 'Number', inv.invoiceNumber);
    row(doc, 'Issue date', inv.issueDate);
    if (inv.dueDate) row(doc, 'Due date', inv.dueDate);
    row(doc, 'Bill to', `${inv.employerName}${inv.gstin ? ` (GSTIN ${inv.gstin})` : ''}`);
    if (inv.billing?.address) row(doc, 'Billing address', [inv.billing.address, inv.billing.city, inv.billing.state, inv.billing.postalCode].filter(Boolean).join(', '));
    if (inv.policyNumber) row(doc, 'Group policy', `${inv.policyNumber} — insurer statement ${inv.insurerStatementRef}`);
    if (inv.period) row(doc, 'Period', inv.period);
    doc.moveDown().fillColor('#087f8c').fontSize(12).text('Lines');
    for (const l of inv.lines) doc.fillColor('#000').fontSize(10).text(`${l.description}`, { continued: true }).text(`  ${rupees(l.amount)}`, { align: 'right' });
    doc.moveDown(0.5).fontSize(11).fillColor('#14283f').text(`Total ${inv.direction === 'credit' ? 'credit' : 'payable'}: ${rupees(inv.total)}`, { align: 'right' });
    row(doc, 'Status', inv.status + (inv.payment ? ` — ${inv.payment.reference} (${inv.payment.method}, test mode)` : ''));
    doc.moveDown().fontSize(9).fillColor('#555').text(inv.type === 'service_fee'
      ? 'VHC corporate service fee for benefits administration (VHC income).'
      : 'Premium is collected on behalf of the insurer and settled to the insurer. It is not VHC revenue.');
  });
}
